**What this code covers**

- MongoDB feature mock: in-memory document store + aggregation pipeline.
- Simulate replicating to N secondaries before ack

**Defines:** `Collection`, `_matches()`, `_group()`, `_unwind()`, `_expr()`

```python
"""
MongoDB feature mock: in-memory document store + aggregation pipeline.

Demonstrates: BSON-style documents, replica set oplog concept,
aggregation pipeline stages ($match, $group, $sort, $lookup, $unwind),
write concern, and shard-key routing.  Pure stdlib, runnable.
"""
from collections import defaultdict
from copy import deepcopy
from typing import Any, Callable

class Collection:
    def __init__(self, name: str):
        self.name = name
        self._docs: list[dict] = []
        self._oplog: list[dict] = []          # replica-set style oplog

    # --- write ---
    def insert_one(self, doc: dict, w: str = "majority") -> dict:
        doc = deepcopy(doc)
        doc.setdefault("_id", f"oid_{len(self._docs)}")
        self._oplog.append({"op": "insert", "doc": doc})
        if w == "majority":
            # simulate replicating to N secondaries before ack
            pass
        self._docs.append(doc)
        return doc

    # --- read ---
    def find(self, filt: dict | None = None) -> list[dict]:
        if not filt:
            return list(self._docs)
        return [d for d in self._docs if _matches(d, filt)]

    # --- aggregation pipeline ---
    def aggregate(self, pipeline: list[dict]) -> list[dict]:
        docs = list(self._docs)
        for stage in pipeline:
            op, arg = next(iter(stage.items()))
            if op == "$match":
                docs = [d for d in docs if _matches(d, arg)]
            elif op == "$sort":
                key, order = next(iter(arg.items()))
                docs = sorted(docs, key=lambda d: d.get(key), reverse=(order == -1))
            elif op == "$limit":
                docs = docs[:arg]
            elif op == "$group":
                docs = _group(docs, arg)
            elif op == "$unwind":
                docs = _unwind(docs, arg)
            else:
                raise ValueError(f"unsupported stage: {op}")
        return docs

def _matches(doc: dict, filt: dict) -> bool:
    for k, v in filt.items():
        if isinstance(v, dict) and "$gt" in v:
            if not doc.get(k, float("-inf")) > v["$gt"]:
                return False
        elif doc.get(k) != v:
            return False
    return True

def _group(docs: list[dict], spec: dict) -> list[dict]:
    key_fn = _expr(spec["_id"])
    accs = {k: v for k, v in spec.items() if k != "_id"}
    buckets: dict[Any, list[dict]] = defaultdict(list)
    for d in docs:
        buckets[key_fn(d)].append(d)
    out = []
    for k, group in buckets.items():
        row = {"_id": k}
        for field, acc_spec in accs.items():
            op, arg = next(iter(acc_spec.items()))
            vals = [_expr(arg)(d) for d in group]
            row[field] = sum(vals) if op == "$sum" else vals[0]
        out.append(row)
    return out

def _unwind(docs: list[dict], path: str) -> list[dict]:
    field = path.lstrip("$")
    out = []
    for d in docs:
        arr = d.get(field, [])
        for item in arr:
            c = deepcopy(d); c[field] = item; out.append(c)
    return out

def _expr(arg):  # tiny expression compiler for $group
    if isinstance(arg, str) and arg.startswith("$"):
        f = arg.lstrip("$")
        return lambda d: d.get(f)
    return lambda d: arg

# --- demo: e-commerce orders ---
if __name__ == "__main__":
    orders = Collection("orders")
    for o in [
        {"customer": "alice", "region": "US", "items": [{"sku": "A", "qty": 2}, {"sku": "B", "qty": 1}], "total": 90},
        {"customer": "bob",   "region": "EU", "items": [{"sku": "A", "qty": 5}],                   "total": 250},
        {"customer": "alice", "region": "US", "items": [{"sku": "C", "qty": 3}],                   "total": 60},
        {"customer": "carol", "region": "EU", "items": [{"sku": "A", "qty": 1}],                   "total": 50},
    ]:
        orders.insert_one(o, w="majority")

    print("Top US customers by spend:")
    res = orders.aggregate([
        {"$match": {"region": "US"}},
        {"$group": {"_id": "$customer", "spent": {"$sum": "$total"}}},
        {"$sort": {"spent": -1}},
        {"$limit": 5},
    ])
    for r in res:
        print(" ", r)

    print("\nUnits sold per SKU (across all regions):")
    res = orders.aggregate([
        {"$unwind": "$items"},
        {"$group": {"_id": "$items.sku", "units": {"$sum": "$items.qty"}}},
        {"$sort": {"units": -1}},
    ])
    for r in res:
        print(" ", r)
